  // ---- src/js/modules/scramble.js ----
  const GLYPHS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789<>/\\|";

  function scrambleOne(el, { duration = 900 } = {}) {
    return new Promise((resolve) => {
      if (!el) {
        resolve();
        return;
      }

      const finalText = el.dataset.scramble || el.textContent.replace(/\u00A0/g, " ");
      el.textContent = finalText;
      el.classList.remove("is-magnetic");

      const length = finalText.length;
      const start = performance.now();
      let frame = 0;

      function update(now) {
        const progress = Math.min(1, (now - start) / duration);
        const reveal = Math.floor(progress * length);
        let output = "";

        for (let i = 0; i < length; i += 1) {
          if (finalText[i] === " ") {
            output += " ";
            continue;
          }
          if (i < reveal) output += finalText[i];
          else output += GLYPHS[(frame + i) % GLYPHS.length];
        }

        el.textContent = output;
        frame += 1;

        if (progress < 1) requestAnimationFrame(update);
        else {
          el.textContent = finalText;
          resolve();
        }
      }

      requestAnimationFrame(update);
    });
  }

  function scrambleText(el, { duration = 900, onComplete } = {}) {
    if (!el) return;

    const lines = el.querySelectorAll("[data-scramble]");
    const targets = lines.length ? [...lines] : [el];

    Promise.all(targets.map((target, index) =>
      scrambleOne(target, { duration: duration + index * 120 })
    )).then(() => onComplete?.());
  }


  // ---- src/js/modules/magneticType.js ----
  function splitLine(lineEl) {
    const text = (lineEl.dataset.scramble || lineEl.textContent).replace(/\u00A0/g, " ").trim();
    lineEl.textContent = "";
    lineEl.classList.add("is-magnetic");
    const letters = [];

    for (const ch of text) {
      const span = document.createElement("span");
      span.className = "magnet-letter";
      span.textContent = ch;
      lineEl.appendChild(span);
      letters.push(span);
    }

    return letters;
  }

  function createMagneticType(rootEl, { reducedMotion = false } = {}) {
    if (!rootEl || reducedMotion) {
      return { setPointer() {}, split() {}, destroy() {} };
    }

    let letters = [];
    const lines = () => [...rootEl.querySelectorAll(".hero__name-line")];

    function split() {
      letters = [];
      rootEl.classList.add("is-stacked");
      for (const line of lines()) {
        letters.push(...splitLine(line));
      }
    }

    function setPointer(clientX, clientY) {
      if (!letters.length) return;
      for (const span of letters) {
        const rect = span.getBoundingClientRect();
        const cx = rect.left + rect.width / 2;
        const cy = rect.top + rect.height / 2;
        const dx = clientX - cx;
        const dy = clientY - cy;
        const dist = Math.hypot(dx, dy);
        if (dist < 120 && dist > 0.01) {
          const force = (1 - dist / 120) * 12;
          const ox = (dx / dist) * force;
          const oy = (dy / dist) * force;
          span.style.transform = `translate3d(${ox.toFixed(2)}px, ${oy.toFixed(2)}px, 0) scale(${(1 + force * 0.01).toFixed(3)})`;
        } else {
          span.style.transform = "translate3d(0,0,0) scale(1)";
        }
      }
    }

    return {
      split,
      setPointer,
      destroy() {
        for (const line of lines()) {
          line.textContent = line.dataset.scramble || line.textContent;
          line.classList.remove("is-magnetic");
        }
        rootEl.classList.remove("is-stacked");
        letters = [];
      },
    };
  }


